167	     *  a move the user's role may not make by the sheet's permission matrix (403), settling by the user who opened the claim (403), settling a deferred claim (409), settling a PENDING claim (409: it is
168	     *  approved or rejected instead), and any move of a claim dated in a closed period (423). A
169	     *  clerk settling a claim whose due is above the sheet's clerk limit sends it to PENDING. Settling
170	     *  a claim whose due is above the proof threshold in force on its date while it has no proof is
171	     *  refused (422) before the clerk limit is considered. */
172	    @Transactional
173	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus to) {
174	        Claim claim = claims.findForUpdate(id, sheetId)
175	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
176	        refuseIfClosed(sheetId, claim.getDate());
177	        switch (to) {
178	            case OPEN -> settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
179	            case SETTLED -> settings.refuseUnlessAllowed(sheetId, user, Permission.SETTLE);
180	            case VOID -> settings.refuseUnlessAllowed(sheetId, user, Permission.VOID);
181	            default -> {
182	            }
183	        }
184	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
185	                || !claim.getStatus().canMoveTo(to)) {
186	            throw new ResponseStatusException(HttpStatus.CONFLICT,
187	                    "A " + claim.getStatus() + " claim cannot become " + to);
188	        }
189	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
190	            throw new ResponseStatusException(HttpStatus.CONFLICT,
191	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
192	        }
193	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
194	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
195	                    "The user who opened a claim cannot settle it");
196	        }
197	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
198	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
199	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
200	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
201	        if (to == ClaimStatus.SETTLED) {
