217	        } else if (to == ClaimStatus.SETTLED) {
218	            claim.setSettledDue(settling);
219	        }
220	        claims.flush();
221	        logStatus(user, person, claim);
222	        String event = switch (to) {
223	            case OPEN -> "CLAIM_OPENED";
224	            case PENDING -> "CLAIM_PENDING";
225	            case SETTLED -> "CLAIM_SETTLED";
226	            case VOID -> "CLAIM_VOIDED";
