291	     *  when dated in a closed period, and (409) when SETTLED or VOID. */
292	    @Transactional
293	    public Claim addProof(String sheetId, String user, long id) {
294	        Claim claim = claims.findForUpdate(id, sheetId)
295	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
296	        refuseIfClosed(sheetId, claim.getDate());
