309	    /** Refuse (422) settling or approving a claim at a due (null: n/a) above the proof threshold in
310	     *  force on its date while it has no proof. */
311	    private void refuseIfUnproven(Claim claim, BigDecimal due) {
312	        if (claim.getProofs() > 0 || due == null) {
313	            return;
314	        }
315	        BigDecimal threshold = sheets.proofThresholdOn(claim.getSheetId(), claim.getDate());
316	        if (threshold != null && due.compareTo(threshold) > 0) {
317	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
318	                    "A claim whose due is above the proof threshold needs a proof first");
319	        }
320	    }
321	
322	    /** A steward re-settles a SETTLED claim: its due is frozen again at the figure it would show
323	     *  today as an open claim bound by no statement (today's rates, grades, floor and late
324	     *  charge). Refused (404) when missing, (423) when dated in a closed period, (403) for anyone
325	     *  but a steward, and (409) unless SETTLED. */
326	    @Transactional
327	    public Claim resettle(String sheetId, String user, long id) {
328	        Claim claim = claims.findForUpdate(id, sheetId)
329	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
330	        refuseIfClosed(sheetId, claim.getDate());
331	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
332	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
333	        }
334	        if (claim.getStatus() != ClaimStatus.SETTLED) {
335	            throw new ResponseStatusException(HttpStatus.CONFLICT,
336	                    "Only a SETTLED claim is re-settled, not a " + claim.getStatus() + " one");
337	        }
338	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
339	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
340	        RollupService.Snapshot before = rollup.snapshot(sheetId);
341	        BigDecimal old = claim.getSettledDue();
342	        BigDecimal due = LateCharge.of(sheets.find(sheetId)).addToOpen(claim, dueOf(claim, person), roundingOf(claim));
343	        claim.setSettledDue(due);
344	        claims.flush();
345	        logStatus(user, person, claim);
346	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(),
347	                " old=" + dueText(old) + " new=" + dueText(due));
348	        rollup.recordChanges(sheetId, user, before);
349	        return claim;
350	    }
351	
352	    /** A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by the
353	     *  person's last statement if that statement bound it. Refused (409) unless PENDING, (403) for
354	     *  a clerk, and (423) when it is dated in a closed period. */
355	    @Transactional
356	    public Claim reject(String sheetId, String user, long id, String reason) {
357	        Claim claim = pendingForSteward(sheetId, user, id);
358	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
359	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
360	        RollupService.Snapshot before = rollup.snapshot(sheetId);
361	        claim.setStatus(ClaimStatus.OPEN);
362	        claims.flush();
363	        logStatus(user, person, claim);
364	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), " reason=" + reason);
365	        rollup.recordChanges(sheetId, user, before);
366	        return claim;
367	    }
368	
369	    /** A steward (or a role the permission matrix lets reassign) moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
370	     *  number and date, is listed as the new person's newest claim, and loses any figure a
371	     *  statement bound it to (live again until the new person's next statement). Refused (404)
372	     *  when the claim or person is missing, (423) when it is dated in a closed period, (403) for a
373	     *  role the sheet's permission matrix does not let reassign, (409) when SETTLED or VOID or already the person's, and (422) when it is dated after
374	     *  the new person's retirement date. */
375	    @Transactional
376	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
377	        Claim claim = claims.findForUpdate(id, sheetId)
378	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
379	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
380	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
381	        refuseIfClosed(sheetId, claim.getDate());
382	        settings.refuseUnlessAllowed(sheetId, user, Permission.REASSIGN);
383	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
384	            throw new ResponseStatusException(HttpStatus.CONFLICT,
385	                    "A " + claim.getStatus() + " claim cannot be reassigned");
386	        }
387	        if (claim.getPersonId() == toPersonId) {
388	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
389	        }
390	        refuseIfRetired(to, claim.getDate());
391	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
392	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
393	        RollupService.Snapshot before = rollup.snapshot(sheetId);
394	        claim.setPersonId(to.getId());
395	        claim.unbind();
396	        claim.setListed(claims.findLastListed(sheetId) + 1);
397	        claims.flush();
398	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
399	                " from=" + from.getName() + " to=" + to.getName());
400	        rollup.recordChanges(sheetId, user, before);
401	        return claim;
402	    }
403	
404	    /** The PENDING claim a steward decides on: refused (404) when missing, (423) when dated in a
405	     *  closed period, (409) unless PENDING, and (403) when the user is not a steward. */
406	    private Claim pendingForSteward(String sheetId, String user, long id) {
407	        Claim claim = claims.findForUpdate(id, sheetId)
408	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
409	        refuseIfClosed(sheetId, claim.getDate());
410	        if (claim.getStatus() != ClaimStatus.PENDING) {
411	            throw new ResponseStatusException(HttpStatus.CONFLICT,
412	                    "Only a PENDING claim is approved or rejected, not a " + claim.getStatus() + " one");
413	        }
414	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
415	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
416	                    "Only a steward approves or rejects a PENDING claim");
417	        }
418	        return claim;
419	    }
420	
421	    /** Write the claim's status now to its log: by the user, on the sheet's today, with the due
422	     *  it shows at this moment. */
423	    private void logStatus(String user, Person person, Claim claim) {
424	        BigDecimal due = shownDueOf(claim, person);
425	        log.save(new ClaimLog(claim.getSheetId(), claim.getId(), claim.getStatus(), user,
426	                sheets.today(claim.getSheetId()), due == null ? null : due.setScale(2, RoundingMode.HALF_EVEN)));
427	    }
428	
429	    private static String dueText(BigDecimal due) {
430	        return due == null ? "n/a" : due.toPlainString();
431	    }
432	
433	    /** Take a statement of a person: record their due-total now, and bind each of their claims
434	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
435	     *  are left unbound. */
436	    @Transactional
437	    public Statement statement(String sheetId, String user, long personId) {
438	        Person person = people.findForUpdate(personId, sheetId)
439	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
440	        LocalDate today = sheets.today(sheetId);
441	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
442	        RollupService.Snapshot before = rollup.snapshot(sheetId);
443	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person, today)).toList();
444	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
445	        for (Claim c : theirs) {
446	            if (counts(c, person, today)) {
447	                // the statement binds the figure; the late charge keeps following the sheet's today
448	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
449	            } else {
450	                c.unbind();
451	            }
452	        }
453	        claims.flush();
454	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
455	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
456	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
457	        rollup.recordChanges(sheetId, user, before);
458	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
459	    }
460	
461	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
462	     *  and the sheet's today on or after it) the next within the period containing the date
463	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
464	    private String nextNumber(String sheetId, LocalDate date) {
465	        if (!sheets.periodNumberingOn(sheetId)) {
466	            return String.valueOf(sheets.nextClaimNumber(sheetId));
467	        }
468	        // held until the transaction ends, so two claims opened at once are numbered one after the other
469	        sheets.lock(sheetId);
470	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
471	        int last = claims.findNumbers(sheetId).stream()
472	                .filter(n -> n.startsWith(prefix))
473	                .map(n -> n.substring(prefix.length()))
474	                .filter(n -> n.matches("\\d{1,9}"))
475	                .mapToInt(Integer::parseInt)
476	                .max().orElse(0);
477	        return prefix + (last + 1);
478	    }
479	
480	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
481	     *  the transaction ends so a period cannot be closed meanwhile. */
482	    private void refuseIfClosed(String sheetId, LocalDate date) {
483	        sheets.lock(sheetId);
484	        periods.refuseIfClosed(sheetId, date);
485	    }
486	
487	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
488	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
489	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
490	        if (amount.signum() >= 0) {
491	            return null;
492	        }
493	        if (corrects == null
494	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
495	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
496	                    "A negative amount must correct a settled claim of the same person");
497	        }
498	        return corrects;
499	    }
500	
501	    /** Refuse (422) a claim dated after its person's retirement date. */
502	    private static void refuseIfRetired(Person person, LocalDate date) {
503	        if (person.retiredBefore(date)) {
504	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
505	                    "The date is after the person's retirement date");
506	        }
507	    }
508	
509	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
510	     *  do, but not an open one dated within a hold of its person unless bound by a statement, nor
511	     *  one deferred on the sheet's today. */
512	    private static boolean counts(Claim c, Person person, LocalDate today) {
513	        return c.getStatus() == ClaimStatus.SETTLED
514	                || (c.getStatus().isOpen() && !c.isDeferredOn(today) && (c.isBound() || !person.heldOn(c.getDate())));
515	    }
516	
517	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
518	     *  charge on top. */
519	    private BigDecimal shownDueOf(Claim claim, Person person) {
520	        if (claim.getSettledDue() != null) {
521	            return claim.getSettledDue();
522	        }
523	        return LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim));
524	    }
525	
526	    /** A claim's figure before any late charge: the one a statement bound it to (null: n/a), else
527	     *  (unbound, or PENDING) its live due. */
528	    private BigDecimal figureOf(Claim claim, Person person) {
529	        return claim.isBound() ? claim.getStatedDue() : dueOf(claim, person);
530	    }
531	
532	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
533	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
534	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
535	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
536	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
537	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
538	            return null;
539	        }
540	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
541	    }
542	
543	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
544	     *  100, rounded as its rounding policy has it, raised to the sheet's floor in force on its date (a correction's never is); null with no rate in force then. */
545	    private BigDecimal dueOf(Claim claim, Person person) {
546	        BigDecimal floor = sheets.floorOn(claim.getSheetId(), claim.getDate());
547	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
548	                .map(Rate::getPct)
549	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
550	                .map(due -> claim.isCorrection() ? due : due.max(floor))
551	                .orElse(null);
552	    }
553	
554	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
555	     *  correction the date of the claim it corrects. */
556	    private RoundingMode roundingOf(Claim claim) {
557	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
558	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
559	                        .map(Claim::getDate).orElse(claim.getDate());
560	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
561	    }
562	
563	    private void record(String event, String user, Person person, Claim claim) {
564	        record(event, user, person, claim, claim.getNumber());
565	    }
566	
567	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
568	    private void record(String event, String user, Person person, Claim claim, String number) {
569	        record(event, user, person, claim, number, "");
570	    }
571	
572	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
573	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
574	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
575	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
576	    }
577	
578	    private static String noteOf(String note) {
579	        return note == null ? "" : note.trim();
580	    }
581	}
