test("split claim scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "0");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const c_ben_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ben", "amount": "0.40"}, p_ben));
  const c_ben_1 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "7.77", "date": "2026-02-10"}));
  const c_ben_2 = ui.must(await ui.addClaimTwice(pg_uma, p_ben, {"amount": "3.33", "date": "2026-02-10"}));
  expect(await ui.claimCount(pg_uma, p_ben)).toBe(3);
  expect(await ui.claimAction(pg_uma, c_ben_0, "void")).toBe(true);
  const c_ben_3 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.35", "date": "2026-03-09"}));
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_ben_3, "open")).toBe(true);
  expect(await ui.retire(pg_uma, p_cam, "2026-03-05")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50", "from": "2026-03-16", "to": "2026-03-25"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "C"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  await ui.refresh(pg_uma);
  const c_ada_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ada", "amount": "12.50"}, p_ada));
  const c_ada_1 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ada", "amount": "7.77"}, p_ada));
  await ui.setToday(pg_uma, "2026-04-13");
  expect(await ui.addClaim(pg_uma, p_cam, {"amount": "1.00", "date": "2026-04-02"})).toBeNull();
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00", "from": "2026-03-01"})).toBe(true);
  await ui.refresh(pg_uma);
  await ui.expectAudit(sheet, [
    `SETTING_CHANGED sheet=${sheet} by=uma key=clerk-limit value=1.50`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=terms value=10`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=policy-date value=2026-03-05`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=terms-C value=3`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=proof-threshold value=3.00`,
    `ROLE_SET sheet=${sheet} by=uma user=vic role=viewer`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=grace-days value=0`,
    `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00`,
    `RATE_SET sheet=${sheet} by=uma grade=B rate=7.50`,
    `PERIOD_ADDED sheet=${sheet} by=uma period=P1 from=2026-03-01 to=2026-03-15`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=A`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=A`,
    `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=0.40 date=2026-03-10`,
    `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=7.77 date=2026-02-10`,
    `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=3.33 date=2026-02-10`,
    `CLAIM_VOIDED sheet=${sheet} by=uma person=Ben amount=0.40 date=2026-03-10`,
    `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=10.35 date=2026-03-09`,
    `STATEMENT sheet=${sheet} by=uma name=Cam due-total=0.00 claims=0`,
    `STATEMENT sheet=${sheet} by=uma name=Cam due-total=0.00 claims=0`,
    `CLAIM_OPENED sheet=${sheet} by=uma person=Ben amount=10.35 date=2026-03-09 number=1`,
    `PERSON_RETIRED sheet=${sheet} by=uma name=Cam from=2026-03-05`,
    `RATE_SET sheet=${sheet} by=uma grade=C rate=12.50 from=2026-03-16 to=2026-03-25`,
    `PERSON_EDITED sheet=${sheet} by=uma name=Cam grade=C`,
    `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00 from=2026-03-01`,
    `STATEMENT sheet=${sheet} by=uma name=Ada due-total=0.00 claims=0`,
    `STATEMENT sheet=${sheet} by=uma name=Cam due-total=n/a claims=0`,
    `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=12.50 date=2026-03-10`,
    `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=7.77 date=2026-03-10`,
    `PERIOD_CLOSED sheet=${sheet} by=uma period=P1 total=2.07 auto=yes`,
    `RATE_SET sheet=${sheet} by=uma grade=B rate=10.00 from=2026-03-01`
  ]);
});
test("split claim scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
